const TYPE_INDEX = new Map();
for (const def of CONTROLS) {
  def.propIndex = new Map(def.props.map((p) => [p.name, p]));
  for (const type of def.types) TYPE_INDEX.set(type.toLowerCase(), def);
}
SCREEN_DEF.propIndex = new Map(SCREEN_DEF.props.map((p) => [p.name, p]));
COMPONENT_DEF.propIndex = new Map(COMPONENT_DEF.props.map((p) => [p.name, p]));
APP_DEF.propIndex = new Map(APP_DEF.props.map((p) => [p.name, p]));

const UNKNOWN_DEF = {
  id: 'Unknown',
  get label() { return t('catalog.unknownControl'); },
  renderer: 'unknown',
  icon: 'unknown',
  defaults: { ...CLASSIC_POS_DEFAULTS, Width: '=160', Height: '=40', ...LAYOUT_CHILD_DEFAULTS },
  props: [...POSITION, ...VISIBILITY],
  propIndex: new Map(),
  unknown: true,
};

/** "Classic/Button@2.2.0" -> { base: "Classic/Button", version: "2.2.0" } */
export function splitControlType(type) {
  const s = String(type ?? '');
  const at = s.lastIndexOf('@');
  if (at < 0) return { base: s, version: null };
  return { base: s.slice(0, at), version: s.slice(at + 1) };
}

export function controlDef(node) {
  const type = node?.head?.Control;
  if (!type) return UNKNOWN_DEF;
  const { base } = splitControlType(type);
  return TYPE_INDEX.get(base.toLowerCase()) || UNKNOWN_DEF;
}

export function isKnownControlType(type) {
  const { base } = splitControlType(type);
  return TYPE_INDEX.has(base.toLowerCase());
}
